      "ruler_name": "Sheikh Hasina",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "8B",
      "rubric_version": "chapter_8b_v3",
      "calibration_batch_id": "chapter-judge:2022-lean-v4-judges-v1:2022:8B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:USA:15810",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:NGA:15787",
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706"
      ],
      "score_1_to_10": 7.0,
      "insufficient_evidence_reason": null,
      "confidence_score": 86,
      "plausible_score_range": {
        "lower": 6.5,
        "upper": 7.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E061",
          "explanation": "Concrete procurement reform under the Hasina administration with measurable cost, timing, and integrity improvements."
        },
        {
          "evidence_id": "E094",
          "explanation": "PM-chaired Delta Plan implementation machinery shows real institutional conversion, not just aspiration."
        },
        {
          "evidence_id": "E098",
          "explanation": "IMF crisis-response agreement shows active macro stabilization under the government during late 2022."
        },
        {
          "evidence_id": "E100",
          "explanation": "World Bank retrospective links 2022 poverty reduction and social gains to long-run policy execution, though not solely to one 2022 decision."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E055",
          "explanation": "Central-bank leadership remains institutionally close to the executive, which weakens the independence/competence reading."
        },
        {
          "evidence_id": "E098",
          "explanation": "Macroeconomic stress and reserve pressure show that execution was real but not cleanly successful across the whole portfolio."
        }
      ],
      "inherited_baseline_and_constraints": "Bangladesh starts from a dominant-party, partially constrained institutional environment with weak accountability and rule-of-law priors, plus inflation, reserve pressure, and climate risk. Those constraints limit how far 2022 success can be credited to ruler skill alone.",
      "ruler_attribution": "Strong on cabinet-level ownership and implementation; weaker on proving Hasina personally authored every measure. Some gains are long-run or ministerial rather than uniquely personal.",
      "supported_lenses": [
        "8B.1",
        "8B.2",
        "8B.3",
        "8B.4",
        "8B.5",
        "8B.6",
        "8B.7",
        "8B.8",
        "8B.9",
        "8B.10"
      ],
      "missing_or_weak_lenses": [
        "8B.8 is weaker than the rest because course correction is visible but not always tied to direct personnel replacement.",
        "8B.7 is partly lagged and partly retrospective, so outcome credit is real but not fully settled."
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E055",
          "explanation": "Appointment evidence supports competence, but the same item also suggests executive closeness rather than independence."
        },
        {
          "evidence_id": "E098",
          "explanation": "The IMF agreement was reactive to reserve loss, inflation, and external pressure, so it cannot be read as a clean success story."
        }
      ],
      "source_mix": "Official budget and planning documents, IGO macro and implementation assessments, and limited media corroboration. The mix is strong on program and execution mechanics, moderate on independently audited outcomes.",
      "structured_prior_summary": "Local priors are mixed to weak on accountability and rule of law, but government-effectiveness priors are only moderately negative. That is consistent with a capable but imperfect administration in 2022.",
      "chapter_rationale": "Hasina scores as a generally effective executor of a broad governing program in 2022: macro stabilization, social protection, digital procurement, climate-planning institutions, and pandemic-response carryover all show real conversion from speech to machinery to observable results. The positive evidence is not just declarative; it includes budget allocations, PM-chaired implementation bodies, procurement reform, IMF coordination, and later outcome reports on growth and poverty. The main limits are attribution and durability: some gains are ministerial or long-run, some evidence is retrospective, and macro stress remained visible. Moral judgments about authoritarianism do not affect this score. This is above the midpoint because the record shows repeated, ruler-linked implementation across several policy lines, but below the highest tier because execution was uneven and some gains remain partly confounded by inherited momentum and external shocks.",
      "lower_anchor_rejected": "A 6.0 anchor would understate the breadth of concrete implementation, especially in procurement, planning, and macro stabilization.",
      "higher_anchor_rejected": "An 8.5 anchor would overread the evidence: the record shows real execution, but not uniformly durable, independently audited mastery across the whole portfolio.",
      "manual_review_required": false,
