        },
        {
          "field": "lens_gaps",
          "value": "Attribution and outcome durability are stronger than the direct personal-command record."
        },
        {
          "field": "defensible_score_range",
          "value": "6.5-7.5"
        }
      ]
    },
    {
      "dossier_job_key": "dossier:2022-top20-hybrid-v2:2022:BRA:19646",
      "iso3": "BRA",
      "ruler_id": "3413",
      "ruler_year_id": 19646,
      "ruler_name": "Jair Bolsonaro",
      "period_start_year": 2022,
      "period_end_year": 2022,
      "chapter_id": "8B",
      "rubric_version": "chapter_8b_v3",
      "calibration_batch_id": "chapter-judge:2022-lean-v4-judges-v1:2022:8B",
      "calibrated_against": [
        "dossier:2022-top20-hybrid-v2:2022:USA:15810",
        "dossier:2022-top20-hybrid-v2:2022:DEU:16984",
        "dossier:2022-top20-hybrid-v2:2022:NGA:15787",
        "dossier:2022-top20-hybrid-v2:2022:RUS:15706"
      ],
      "score_1_to_10": 4.5,
      "insufficient_evidence_reason": null,
      "confidence_score": 88,
      "plausible_score_range": {
        "lower": 4.0,
        "upper": 5.5
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E092",
          "explanation": "Campaign program filing shows explicit policy priorities and revealed goals for the 2022 race."
        },
        {
          "evidence_id": "E093",
          "explanation": "The election-year package shows real state mobilization and spending, even if politically opportunistic."
        },
        {
          "evidence_id": "E085",
          "explanation": "Public pressure on Petrobras shows direct use of presidential authority over a state company."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E080",
          "explanation": "Large-scale election disinformation and falsehood production cut against competence in truthfulness and governance."
        },
        {
          "evidence_id": "E083",
          "explanation": "Electoral-court sanction over bad-faith litigation shows serious post-election institutional abuse."
        },
        {
          "evidence_id": "E086",
          "explanation": "Repeated politicized intervention in Petrobras culminated in executive ouster and policy churn."
        }
      ],
      "inherited_baseline_and_constraints": "Brazil entered 2022 with functioning institutions and strong formal checks, so Bolsonaro could not rely on pure command power. That makes the record especially revealing: he could mobilize state resources and campaign machinery, but not translate them into durable, non-electoral governing effectiveness.",
      "ruler_attribution": "Strong for campaign-state linkage and Petrobras pressure; weaker for proving broad policy competence. Much of the record is about power retention rather than stable administrative execution.",
      "supported_lenses": [
        "8B.1",
        "8B.2",
        "8B.3",
        "8B.4",
        "8B.5",
        "8B.6",
        "8B.7",
        "8B.8",
        "8B.9",
        "8B.10"
      ],
      "missing_or_weak_lenses": [
        "8B.7 is weak because some apparent output is electoral and not durable policy success.",
        "8B.8 is weak because adaptation mostly took the form of more pressure and messaging, not corrective learning."
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E092",
          "explanation": "The campaign program shows a defined agenda, but it is not an implementation audit."
        },
        {
          "evidence_id": "E093",
          "explanation": "The election-year package demonstrates mobilization, but much of it was politically motivated and not durable."
        }
      ],
      "source_mix": "Mostly official/legal and reputable media evidence, with independent rights-monitor and fact-check synthesis. Strong for revealing Bolsonaro's style of governance, weaker for durable policy success.",
      "structured_prior_summary": "The priors point to unusually strong accountability and rule-of-law capacity relative to the rest of the batch, which makes Bolsonaro's failures in truthful administration and campaign abuse stand out more sharply.",
      "chapter_rationale": "Bolsonaro had a clear revealed program in 2022: hold power, defend a political narrative, pressure state assets, and use election-year state capacity aggressively. The record shows he could mobilize resources and dominate the campaign environment, but the execution pattern was brittle and often self-defeating. Disinformation, bad-faith litigation, and repeated politicization of Petrobras show forceful control without broad administrative competence. The positive items are real but mostly tactical: program filing, election-year spending, and state-company pressure. They do not show durable policy improvement or disciplined governance. Moral judgments about the content of Bolsonaro's politics are excluded here; the score is low because the evidence shows unstable, high-conflict execution that served short-term power goals but not coherent governing effectiveness.",
      "lower_anchor_rejected": "A 3.5 anchor would understate the genuine ability to mobilize state and campaign machinery and to force through some tactical actions.",
      "higher_anchor_rejected": "A 5.5 anchor would overstate the quality of execution; most visible successes were short-term, conflict-driven, and not clearly durable.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
      "chapter_specific": [
        {
          "field": "program_basis",
          "value": "explicit"
        },
