          "field": "operationalization",
          "value": "mixed"
        },
        {
          "field": "mobilization_and_coordination",
          "value": "mixed"
        },
        {
          "field": "adaptation",
          "value": "rigid"
        },
        {
          "field": "goal_progress",
          "value": "mixed"
        },
        {
          "field": "durability",
          "value": "fragile"
        },
        {
          "field": "morality_separation_check",
          "value": "The score reflects execution, not approval of Bolsonaro's objectives."
        },
        {
          "field": "lens_gaps",
          "value": "Durable policy delivery and corrective adaptation are much weaker than campaign control and institutional pressure."
        },
        {
          "field": "defensible_score_range",
          "value": "4.0-5.5"
        }
      ]
    },
